options.dotDiagram:
digraph jarvis_arch {
  rankdir=LR; bgcolor="transparent"; compound=true; pad=0.4; nodesep=0.28; ranksep=1.0;
  fontname="Helvetica"; fontcolor="#8b949e"; labelloc="t"; fontsize=14;
  node [style="filled,rounded", shape=box, fontname="Helvetica", fontcolor="#e6edf3", color="#2a2d3a", fillcolor="#1b1f2a", fontsize=10, margin="0.11,0.06"];
  edge [color="#3a3f4b", fontcolor="#8b949e", fontname="Helvetica", fontsize=9];

  subgraph cluster_clients {
    label="Clients"; style="rounded,filled"; fillcolor="#0f1320"; color="#2a2d3a"; fontcolor="#8b949e";
    iphone [label="iPhone\n(Jarvis app)", fillcolor="#1f3a6b"];
  }

  subgraph cluster_m4 {
    label="M4 Mini  <m4-mini-ip>"; style="rounded,filled"; fillcolor="#0f1320"; color="#2a2d3a"; fontcolor="#00d4ff";
    desktop [label="Ion Desktop", fillcolor="#1f3a6b"];
  }

  subgraph cluster_m2 {
    label="M2 Mini  <mac-mini-ip>  (health-colored)"; style="rounded,filled"; fillcolor="#0f1320"; color="#2a2d3a"; fontcolor="#00d4ff";

  "ion" [label="ion engine  :21017\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "vector" [label="vec-server  :9876\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "apple-foundation" [label="apple-foundation  :9878\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "discord-bot" [label="discord-bot\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "imessage" [label="imessage\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "ion-relay" [label="ion-relay  :8443\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "cloudflared" [label="cloudflared\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "ollama" [label="Ollama embed  :11435\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "deploy-watchdog" [label="deploy-watchdog\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "log-patrol" [label="log-patrol\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "nas-mount" [label="nas-mount\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "disk" [label="disk\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "routines" [label="scheduler routines\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];
  "runaway" [label="runaway guard\n${status}", fillcolor="${fillcolor}", fontcolor="#ffffff"];

    // structural (not health-probed) — neutral
    chroma [label="ChromaDB", shape=cylinder, fillcolor="#16241b"];
    neo4j  [label="Neo4j / Graphiti", shape=cylinder, fillcolor="#16241b"];
    sqlite [label="SQLite\n~/.jarvis", shape=cylinder, fillcolor="#16241b"];
    alloy  [label="Alloy\n:12345", fillcolor="#243044"];
    loki   [label="Loki\n:3100", shape=cylinder, fillcolor="#16241b"];
    grafana[label="Grafana\n:3000", fillcolor="#243044"];
  }

  subgraph cluster_ext {
    label="External"; style="rounded,filled"; fillcolor="#0f1320"; color="#2a2d3a"; fontcolor="#8b949e";
    nas [label="NAS  <nas-ip>", shape=box3d, fillcolor="#241b16"];
    claude [label="Anthropic\nClaude (CLI)", fillcolor="#2a1f3a"];
    openrouter [label="OpenRouter", fillcolor="#2a1f3a"];
    cflare [label="Cloudflare\nrelay.<your-domain>", fillcolor="#2a1f3a"];
  }

  subgraph cluster_legend {
    label="Health"; style="rounded,filled"; fillcolor="#0f1320"; color="#2a2d3a"; fontcolor="#8b949e"; rank=sink;
    lg_ok [label="ok", fillcolor="#1a7f37", fontcolor="#ffffff"];
    lg_wn [label="warn", fillcolor="#9e6a03", fontcolor="#ffffff"];
    lg_dn [label="down", fillcolor="#a40e26", fontcolor="#ffffff"];
    lg_ok -> lg_wn -> lg_dn [style=invis];
  }

  // client paths
  iphone -> desktop [label="Bonjour (LAN)"];
  iphone -> cflare [label="WAN", style=dashed];
  cflare -> cloudflared [label="tunnel"];
  cloudflared -> "ion-relay"; "ion-relay" -> ion [label="ws"];
  desktop -> ion [label="LAN :21017"];

  // reasoning
  ion -> claude [label="reasoning"];
  ion -> openrouter [style=dashed, label="some staff"];
  ion -> "apple-foundation" [label="on-device", style=dashed];

  // memory
  ion -> vector [label="recall / remember"];
  vector -> chroma; vector -> neo4j; vector -> sqlite;
  vector -> ollama [label="embeddings"];
  ollama -> nas [style=dotted, label="hosted on"];
  ion -> sqlite [label="events / history"];

  // scheduler + guards (logical, inside ion)
  ion -> routines [style=dashed]; ion -> runaway [style=dashed];

  // channels
  "discord-bot" -> ion; imessage -> ion;

  // ops / automation
  "deploy-watchdog" -> ion [style=dotted, label="redeploy"];
  "log-patrol" -> sqlite [style=dotted];
  "nas-mount" -> nas [style=dotted];

  // observability
  ion -> alloy [style=dotted]; vector -> alloy [style=dotted]; "ion-relay" -> alloy [style=dotted];
  alloy -> loki [label="logs"]; loki -> grafana; sqlite -> grafana [label="SQLite ds"]; disk -> sqlite [style=dotted];
}
